    {"id":"local_089","title":"The Supper at Emmaus","artist":"Caravaggio","year":1601,"period":"Mannerism","style":"Oil on canvas","medium":"Oil and tempera on canvas","dimensions":"141 cm x 196.2 cm","origin":"National Gallery, London","type":"Painting","subject":"Religious","description":"The resurrected Christ reveals himself to two disciples at supper through the gesture of blessing bread.","historicalContext":"Painted for Ciriaco Mattei. Caravaggio's beardless Christ and extreme foreshortening were controversial.","meaning":"The moment of recognition when the ordinary becomes miraculous is captured in explosive reactions.","keySymbols":["blessing gesture","basket on edge","outstretched arms","shadow of Christ"],"creditLine":"National Gallery, London","isPublicDomain":True},
    {"id":"local_090","title":"The Penitent Magdalene","artist":"Titian","year":1565,"period":"High Renaissance","style":"Oil on canvas","medium":"Oil on canvas","dimensions":"128 cm x 103 cm","origin":"Hermitage Museum, St. Petersburg","type":"Painting","subject":"Religious","description":"Mary Magdalene gazes upward with tear-filled eyes, flowing hair partially covering her body, in powerful repentance.","historicalContext":"This late version exemplifies Titian's loose, expressive brushwork that foreshadowed Impressionism.","meaning":"Magdalene's upturned gaze bridges earthly and divine. Through complete surrender comes redemption.","keySymbols":["flowing hair","upturned eyes","tears","ointment jar"],"creditLine":"Hermitage Museum, St. Petersburg","isPublicDomain":True},
    {"id":"local_091","title":"The Adoration of the Shepherds","artist":"Giorgione","year":1505,"period":"High Renaissance","style":"Oil on panel","medium":"Oil on wood panel","dimensions":"91 cm x 111 cm","origin":"National Gallery of Art, Washington D.C.","type":"Painting","subject":"Religious","description":"Shepherds kneel before the newborn Christ in a cave setting with luminous landscape behind.","historicalContext":"Also known as the Allendale Nativity. Most scholars accept it as primarily Giorgione's work.","meaning":"The soft atmospheric light transforms the Nativity into a meditative, dreamlike vision.","keySymbols":["cave entrance","kneeling shepherds","luminous sky","peaceful landscape"],"creditLine":"National Gallery of Art, Washington D.C.","isPublicDomain":True},
    {"id":"local_092","title":"Saint Sebastian","artist":"Andrea Mantegna","year":1480,"period":"Early Renaissance","style":"Tempera on canvas","medium":"Tempera on canvas","dimensions":"255 cm x 140 cm","origin":"Louvre, Paris","type":"Painting","subject":"Religious","description":"Saint Sebastian tied to a classical column, pierced with arrows, set against ruins with meticulous archaeological detail.","historicalContext":"Mantegna's fascination with Roman antiquity is evident. Likely a plague devotion painting.","meaning":"Sebastian's endurance represents the Christian soul's triumph over physical torment.","keySymbols":["arrows","classical ruins","bound figure","cloud formations"],"creditLine":"Louvre, Paris","isPublicDomain":True},
    {"id":"local_093","title":"The Resurrection","artist":"Piero della Francesca","year":1465,"period":"Early Renaissance","style":"Fresco","medium":"Fresco","dimensions":"225 cm x 200 cm","origin":"Museo Civico, Sansepolcro","type":"Painting","subject":"Religious","description":"Christ rises triumphantly from his tomb while four Roman soldiers sleep below. Aldous Huxley called it the greatest painting.","historicalContext":"Painted for Sansepolcro town hall. Survived WWII when a British officer halted shelling of the town.","meaning":"Christ straddles the boundary between death and life, winter and spring.","keySymbols":["resurrection banner","sleeping soldiers","dead and living trees","dawn light"],"creditLine":"Museo Civico, Sansepolcro","isPublicDomain":True},
    {"id":"local_094","title":"Portrait of Federico da Montefeltro","artist":"Piero della Francesca","year":1472,"period":"Early Renaissance","style":"Oil on panel","medium":"Oil and tempera on wood panel","dimensions":"47 cm x 33 cm","origin":"Uffizi Gallery, Florence","type":"Painting","subject":"Portrait","description":"A distinctive profile portrait of the Duke of Urbino showing his famous broken nose and rolling hills behind.","historicalContext":"Federico lost his right eye in a tournament, which is why he is always depicted in left profile.","meaning":"The profile format references ancient Roman coins, asserting authority over Urbino.","keySymbols":["profile view","broken nose","red cap","aerial landscape"],"creditLine":"Uffizi Gallery, Florence","isPublicDomain":True},
    {"id":"local_095","title":"The Madonna of the Pinks","artist":"Raphael","year":1507,"period":"High Renaissance","style":"Oil on yew","medium":"Oil on yew wood","dimensions":"27.9 cm x 22.4 cm","origin":"National Gallery, London","type":"Painting","subject":"Religious","description":"An intimate painting of the Virgin Mary offering pink carnations to the infant Christ, who reaches to accept them.","historicalContext":"Nearly sold as a copy until scientific analysis in 1991 confirmed it as autograph Raphael.","meaning":"Carnations symbolize divine love. The exchange prefigures Christ's Passion.","keySymbols":["pink carnations","intimate scale","window landscape","tender exchange"],"creditLine":"National Gallery, London","isPublicDomain":True},
    {"id":"local_096","title":"The Entombment","artist":"Raphael","year":1507,"period":"High Renaissance","style":"Oil on panel","medium":"Oil on wood panel","dimensions":"184 cm x 176 cm","origin":"Galleria Borghese, Rome","type":"Painting","subject":"Religious","description":"Young men carry Christ's lifeless body to the tomb while the Virgin Mary faints with grief.","historicalContext":"Commissioned by Atalanta Baglioni in memory of her son murdered in a family feud.","meaning":"The physical weight of Christ's body parallels the emotional weight of bereavement.","keySymbols":["limp body","fainting Virgin","rocky Golgotha","empty cross"],"creditLine":"Galleria Borghese, Rome","isPublicDomain":True},
    {"id":"local_097","title":"The Mystic Marriage of St. Catherine","artist":"Correggio","year":1527,"period":"High Renaissance","style":"Oil on panel","medium":"Oil on wood panel","dimensions":"105 cm x 102 cm","origin":"Louvre, Paris","type":"Painting","subject":"Religious","description":"The infant Christ places a ring on Saint Catherine's finger while the Virgin Mary looks on.","historicalContext":"Correggio's soft, sensuous style was revolutionary. His sfumato rivaled Leonardo's.","meaning":"The mystical marriage symbolizes the soul's union with Christ through faith.","keySymbols":["ring","palm of martyrdom","soft light","intimate grouping"],"creditLine":"Louvre, Paris","isPublicDomain":True},
    {"id":"local_098","title":"Venus and Adonis","artist":"Titian","year":1554,"period":"High Renaissance","style":"Oil on canvas","medium":"Oil on canvas","dimensions":"186 cm x 207 cm","origin":"Museo del Prado, Madrid","type":"Painting","subject":"Mythology","description":"Venus desperately tries to restrain Adonis from leaving for the hunt that will end in his death.","historicalContext":"Part of the poesie series for Philip II - visual poems equivalent of Ovid's Metamorphoses.","meaning":"Love cannot protect Adonis from fate. Beauty and love cannot defeat mortality.","keySymbols":["departing hunter","clinging Venus","sleeping Cupid","hunting dogs"],"creditLine":"Museo del Prado, Madrid","isPublicDomain":True},
    {"id":"local_099","title":"Saint Jerome in the Wilderness","artist":"Leonardo da Vinci","year":1482,"period":"High Renaissance","style":"Oil on walnut panel","medium":"Oil and tempera on walnut panel","dimensions":"103 cm x 75 cm","origin":"Vatican Museums, Vatican City","type":"Painting","subject":"Religious","description":"An unfinished painting of the aged Saint Jerome kneeling in a rocky wilderness with a lion at his feet.","historicalContext":"Left unfinished when Leonardo moved to Milan. The panel was cut in two and later reunited.","meaning":"Jerome's anguished expression embodies penitence and the struggle between intellect and faith.","keySymbols":["kneeling saint","lion","rock for beating chest","unfinished state"],"creditLine":"Vatican Museums, Vatican City","isPublicDomain":True},
